package config;

import java.io.IOException;
import java.io.InputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.HashMap;
import java.util.Map;
import java.util.Properties;

/** conf/app.properties, overridable by -Dpoints.KEY, POINTS_KEY env vars, or {@link #with}. */
public final class AppConfig {
    private final Properties props = new Properties();
    private final Map<String, String> overrides = new HashMap<>();

    private AppConfig() {}

    public static AppConfig load() {
        return load(Path.of("conf", "app.properties"));
    }

    public static AppConfig load(Path file) {
        AppConfig cfg = new AppConfig();
        try (InputStream in = Files.newInputStream(file)) {
            cfg.props.load(in);
        } catch (IOException e) {
            throw new IllegalStateException("cannot read config " + file, e);
        }
        return cfg;
    }

    public AppConfig with(String key, String value) {
        AppConfig copy = new AppConfig();
        copy.props.putAll(props);
        copy.overrides.putAll(overrides);
        copy.overrides.put(key, value);
        return copy;
    }

    public String get(String key) {
        if (overrides.containsKey(key)) return overrides.get(key);
        String sys = System.getProperty("points." + key);
        if (sys != null && !sys.isBlank()) return sys.trim();
        String env = System.getenv("POINTS_" + key.toUpperCase().replace('.', '_'));
        if (env != null && !env.isBlank()) return env.trim();
        String v = props.getProperty(key);
        if (v == null) throw new IllegalStateException("missing config key " + key);
        return v.trim();
    }

    public Path ptsBin() { return Path.of(get("pts.bin")); }

    public long ptsTimeoutSeconds() { return Long.parseLong(get("pts.timeoutSeconds")); }

    public Path ptsHome() { return Path.of(get("pts.home")); }

    public long capPerPayment() { return Long.parseLong(get("points.capPerPayment")); }

    public String refPrefix() { return get("points.refPrefix"); }

    public Path dataDir() { return Path.of(get("data.dir")); }
}
package service;

import domain.Member;

import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;

/** Member lookup. Keys are the member number exactly as issued (text, not a number). */
public class MemberDirectory {
    private final Map<String, Member> members = new LinkedHashMap<>();

    public MemberDirectory(List<Member> list) {
        for (Member m : list) {
            String key = key(m.memberNo());
            if (members.putIfAbsent(key, m) != null) {
                throw new IllegalStateException("member number issued twice: " + m.memberNo());
            }
        }
    }

    public Optional<Member> find(String memberNo) {
        return Optional.ofNullable(members.get(key(memberNo)));
    }

    public List<Member> all() {
        return List.copyOf(members.values());
    }

    /** Corporate codes are case-insensitive on the acquirer side ("c7781" == "C7781"). */
    static String key(String memberNo) {
        return memberNo.strip().toUpperCase();
    }
}
package infra;

import domain.Grade;
import domain.Member;
import domain.Payment;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;

/** Fixture/export readers. Values never contain commas. */
public final class CsvFiles {
    private CsvFiles() {}

    public static List<Member> members(Path file) {
        List<Member> out = new ArrayList<>();
        for (String[] r : rows(file)) {
            out.add(new Member(cell(r[0]), r[1], Grade.valueOf(r[2]), r[3]));
        }
        return out;
    }

    public static List<Payment> payments(Path file) {
        List<Payment> out = new ArrayList<>();
        for (String[] r : rows(file)) {
            out.add(new Payment(r[0], cell(r[1]), r[2], Long.parseLong(r[3]), r[4]));
        }
        return out;
    }

    /**
     * The acquirer's payment export is made for spreadsheets: member numbers that start
     * with 0 are written as ="004512" so the spreadsheet keeps them as text.
     */
    static String cell(String raw) {
        String s = raw.strip();
        if (s.startsWith("=\"") && s.endsWith("\"") && s.length() >= 3) {
            return s.substring(2, s.length() - 1);
        }
        if (s.length() >= 2 && s.startsWith("\"") && s.endsWith("\"")) {
            return s.substring(1, s.length() - 1);
        }
        return s;
    }

    private static List<String[]> rows(Path file) {
        try {
            List<String> lines = Files.readAllLines(file, StandardCharsets.UTF_8);
            List<String[]> rows = new ArrayList<>();
            for (int i = 1; i < lines.size(); i++) {
                String l = lines.get(i).strip();
                if (!l.isEmpty()) rows.add(l.split(",", -1));
            }
            return rows;
        } catch (IOException e) {
            throw new IllegalStateException("cannot read " + file, e);
        }
    }
}
