package service;

import domain.Member;
import infra.PtsctlClient;

import java.util.regex.Pattern;

/**
 * Customer-care compensation: points credited by hand-off from the support system, one credit per
 * support ticket. The vendor reference is A-<ticket>; the vendor refuses a reused reference, so a
 * second request for the same ticket fails even after a restart.
 */
public class CompensationService {
    static final String REF_PREFIX = "A";
    /** Vendor reference allows [A-Za-z0-9-], up to 32 characters including the prefix. */
    private static final Pattern TICKET = Pattern.compile("[A-Za-z0-9-]{1,30}");

    private final MemberDirectory members;
    private final PtsctlClient pts;

    public CompensationService(MemberDirectory members, PtsctlClient pts) {
        this.members = members;
        this.pts = pts;
    }

    /** Credits points for one ticket; returns the vendor entry number. Nothing is sent if refused. */
    public synchronized String compensate(String memberNo, long points, String ticketNo) {
        Member m = members.find(memberNo).orElseThrow(() -> new IllegalArgumentException("unknown member " + memberNo));
        if (points <= 0) throw new IllegalArgumentException("points must be positive: " + points);
        if (ticketNo == null || !TICKET.matcher(ticketNo).matches()) {
            throw new IllegalArgumentException("bad ticket number: " + ticketNo);
        }
        return pts.earn(m.memberNo(), points, REF_PREFIX + "-" + ticketNo);
    }
}

